<style>
.eg-dish-modal {
  position: fixed;
  inset: 0;
  z-index: 999999;
  display: flex;
  align-items: center;
  justify-content: center;
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.25s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.25s ease;
  font-family: 'Open Sans', sans-serif;
  padding: 16px;
  box-sizing: border-box;
}
.eg-dish-modal.is-open {
  visibility: visible;
  opacity: 1;
}
.eg-dish-modal .eg-modal-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.eg-dish-modal .eg-modal-card {
  position: relative;
  width: 100%;
  max-width: 680px;
  background: #18181B;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.12);
  transform: translateY(16px) scale(0.97);
  transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 2;
}
.eg-dish-modal.is-open .eg-modal-card {
  transform: translateY(0) scale(1);
}
.eg-dish-modal .eg-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 22px;
  background: #27272A;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.eg-dish-modal .eg-modal-badge {
  display: inline-block;
  font-size: 10.5px;
  font-weight: 800;
  color: #EAB308;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
  text-transform: uppercase;
}
.eg-dish-modal .eg-modal-title {
  margin: 0;
  color: #FFFFFF;
  font-size: 19px;
  font-weight: 800;
  line-height: 1.25;
}
.eg-dish-modal .eg-modal-close {
  background: transparent;
  border: none;
  color: #A1A1AA;
  font-size: 32px;
  line-height: 1;
  cursor: pointer;
  padding: 0 4px;
  transition: color 0.15s ease, transform 0.15s ease;
}
.eg-dish-modal .eg-modal-close:hover {
  color: #FFFFFF;
  transform: scale(1.15);
}
.eg-dish-modal .eg-modal-video-wrap {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  height: 0;
  background: #000000;
  overflow: hidden;
}
.eg-dish-modal .eg-modal-video-wrap iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 0;
}
.eg-dish-modal .eg-modal-body {
  padding: 20px 24px;
  background: #18181B;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.eg-dish-modal .eg-modal-info-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}
.eg-dish-modal .eg-modal-desc {
  margin: 0 0 6px 0;
  color: #D4D4D8;
  font-size: 13.5px;
  line-height: 1.45;
}
.eg-dish-modal .eg-modal-guarantee {
  color: #A1A1AA;
  font-size: 12px;
  font-weight: 500;
}
.eg-dish-modal .eg-modal-price {
  display: inline-block;
  background: #FF5500;
  color: #FFFFFF;
  font-size: 18px;
  font-weight: 800;
  padding: 6px 16px;
  border-radius: 50px;
  white-space: nowrap;
}
.eg-dish-modal .eg-modal-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 16px;
  flex-wrap: wrap;
  gap: 10px;
}
.eg-dish-modal .eg-modal-btn-add {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #FF5500;
  color: #FFFFFF;
  border: none;
  font-family: 'Open Sans', sans-serif;
  font-size: 14px;
  font-weight: 800;
  padding: 11px 24px;
  border-radius: 50px;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(255, 85, 0, 0.35);
  transition: all 0.2s ease;
}
.eg-dish-modal .eg-modal-btn-add:hover {
  background: #E04B00;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255, 85, 0, 0.5);
}
.eg-dish-modal .eg-modal-subhint {
  color: #71717A;
  font-size: 12px;
}
@media (max-width: 600px) {
  .eg-dish-modal .eg-modal-card {
    border-radius: 18px;
  }
  .eg-dish-modal .eg-modal-info-row {
    flex-direction: column-reverse;
  }
  .eg-dish-modal .eg-modal-footer {
    flex-direction: column;
    align-items: stretch;
  }
  .eg-dish-modal .eg-modal-btn-add {
    justify-content: center;
  }
}
</style>
