<div id="eg-dish-modal" class="eg-dish-modal" role="dialog" aria-modal="true" aria-labelledby="eg-modal-dish-title">
  <div class="eg-modal-overlay"></div>
  <div class="eg-modal-card">
    <!-- Header -->
    <div class="eg-modal-header">
      <div class="eg-modal-badge-row">
        <span class="eg-modal-badge">🍽️ ESPECIALIDAD EAT&amp;GO</span>
        <h3 id="eg-modal-dish-title" class="eg-modal-title">Cargando plato...</h3>
      </div>
      <button type="button" class="eg-modal-close" id="eg-modal-close-btn" aria-label="Cerrar modal">&times;</button>
    </div>

    <!-- Video Container (16:9 ratio) -->
    <div class="eg-modal-video-wrap">
      <iframe id="eg-modal-iframe" src="" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe>
    </div>

    <!-- Dish Content & Actions -->
    <div class="eg-modal-body">
      <div class="eg-modal-info-row">
        <div class="eg-modal-desc-col">
          <p id="eg-modal-dish-desc" class="eg-modal-desc">Descripción del plato criollo elaborado con los ingredientes más frescos del día.</p>
          <span class="eg-modal-guarantee">✨ Incluye guarnición criolla • Empaque térmico sellado</span>
        </div>
        <div class="eg-modal-price-col">
          <span id="eg-modal-dish-price" class="eg-modal-price">$0.00</span>
        </div>
      </div>

      <div class="eg-modal-footer">
        <button type="button" id="eg-modal-add-btn" class="eg-modal-btn-add woosq-btn" data-id="">
          <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><line x1="3" x2="21" y1="6" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>
          <span>+ Agregar al Pedido</span>
        </button>
        <span class="eg-modal-subhint">Despacho sin filas en Obarrio y Calle 50</span>
      </div>
    </div>
  </div>
</div>

<style>
.eg-dish-modal {
  position: fixed;
  inset: 0;
  z-index: 999999;
  display: flex;
  align-items: center;
  justify-content: center;
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.25s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.25s ease;
  font-family: 'Open Sans', sans-serif;
  padding: 16px;
  box-sizing: border-box;
}
.eg-dish-modal.is-open {
  visibility: visible;
  opacity: 1;
}
.eg-dish-modal .eg-modal-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.eg-dish-modal .eg-modal-card {
  position: relative;
  width: 100%;
  max-width: 680px;
  background: #18181B;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.85);
  border: 1px solid rgba(255, 255, 255, 0.12);
  transform: translateY(16px) scale(0.97);
  transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 2;
}
.eg-dish-modal.is-open .eg-modal-card {
  transform: translateY(0) scale(1);
}
.eg-dish-modal .eg-modal-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 22px;
  background: #27272A;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.eg-dish-modal .eg-modal-badge {
  display: inline-block;
  font-size: 10.5px;
  font-weight: 800;
  color: #EAB308;
  letter-spacing: 0.5px;
  margin-bottom: 4px;
  text-transform: uppercase;
}
.eg-dish-modal .eg-modal-title {
  margin: 0;
  color: #FFFFFF;
  font-size: 19px;
  font-weight: 800;
  line-height: 1.25;
}
.eg-dish-modal .eg-modal-close {
  background: transparent;
  border: none;
  color: #A1A1AA;
  font-size: 32px;
  line-height: 1;
  cursor: pointer;
  padding: 0 4px;
  transition: color 0.15s ease, transform 0.15s ease;
}
.eg-dish-modal .eg-modal-close:hover {
  color: #FFFFFF;
  transform: scale(1.15);
}
.eg-dish-modal .eg-modal-video-wrap {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  height: 0;
  background: #000000;
  overflow: hidden;
}
.eg-dish-modal .eg-modal-video-wrap iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 0;
}
.eg-dish-modal .eg-modal-body {
  padding: 20px 24px;
  background: #18181B;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.eg-dish-modal .eg-modal-info-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}
.eg-dish-modal .eg-modal-desc {
  margin: 0 0 6px 0;
  color: #D4D4D8;
  font-size: 13.5px;
  line-height: 1.45;
}
.eg-dish-modal .eg-modal-guarantee {
  color: #A1A1AA;
  font-size: 12px;
  font-weight: 500;
}
.eg-dish-modal .eg-modal-price {
  display: inline-block;
  background: #FF5500;
  color: #FFFFFF;
  font-size: 18px;
  font-weight: 800;
  padding: 6px 16px;
  border-radius: 50px;
  white-space: nowrap;
}
.eg-dish-modal .eg-modal-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 16px;
  flex-wrap: wrap;
  gap: 10px;
}
.eg-dish-modal .eg-modal-btn-add {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #FF5500;
  color: #FFFFFF;
  border: none;
  font-family: 'Open Sans', sans-serif;
  font-size: 14px;
  font-weight: 800;
  padding: 11px 24px;
  border-radius: 50px;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(255, 85, 0, 0.35);
  transition: all 0.2s ease;
}
.eg-dish-modal .eg-modal-btn-add:hover {
  background: #E04B00;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(255, 85, 0, 0.5);
}
.eg-dish-modal .eg-modal-subhint {
  color: #71717A;
  font-size: 12px;
}
@media (max-width: 600px) {
  .eg-dish-modal .eg-modal-card {
    border-radius: 18px;
  }
  .eg-dish-modal .eg-modal-info-row {
    flex-direction: column-reverse;
  }
  .eg-dish-modal .eg-modal-footer {
    flex-direction: column;
    align-items: stretch;
  }
  .eg-dish-modal .eg-modal-btn-add {
    justify-content: center;
  }
}
</style>

<script>
jQuery(document).ready(function($) {
  var $modal = $('#eg-dish-modal');
  var $iframe = $('#eg-modal-iframe');
  var $title = $('#eg-modal-dish-title');
  var $price = $('#eg-modal-dish-price');
  var $desc = $('#eg-modal-dish-desc');
  var $addBtn = $('#eg-modal-add-btn');

  var dishVideoMap = {
    '707': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '446': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '423': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '154': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '688': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '685': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '683': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    '680': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0',
    'default': 'https://www.youtube.com/embed/2vjPBrBU-TM?autoplay=1&rel=0'
  };

  function formatEmbedUrl(rawUrl) {
    if (!rawUrl) return dishVideoMap['default'];
    if (rawUrl.indexOf('embed') !== -1) return rawUrl + (rawUrl.indexOf('?') === -1 ? '?autoplay=1' : '&autoplay=1');
    var yId = rawUrl.match(/(?:youtu\.be\/|youtube\.com\/(?:watch\?v=|embed\/|v\/))([a-zA-Z0-9_-]{11})/);
    if (yId && yId[1]) return 'https://www.youtube.com/embed/' + yId[1] + '?autoplay=1&rel=0';
    return rawUrl;
  }

  // Auto-open si la URL contiene #open_video
  if (window.location.hash === '#open_video' || window.location.search.indexOf('open_video') !== -1) {
    setTimeout(function() {
      $('.elementor-781 .elementor-element-c01vclk').first().trigger('click');
    }, 1000);
  }

  // Interceptar clic en el area de foto de la tarjeta del carrusel (Template 781)
  $(document).on('click', '.elementor-781 .elementor-element-c01vclk', function(e) {
    e.preventDefault();
    e.stopPropagation();

    var $card = $(this).closest('.e-loop-item');
    var classes = $card.attr('class') || '';
    var m = classes.match(/post-(\d+)/);
    var pid = m ? m[1] : '';

    var cardTitle = $card.find('.elementor-element-6a7b8c5 h3, .elementor-element-6a7b8c5 .elementor-heading-title').text().trim();
    var cardPrice = $card.find('.elementor-element-4e5f6a3 .woocommerce-Price-amount').first().text().trim();
    if (!cardPrice) { cardPrice = $card.find('.elementor-element-4e5f6a3').first().text().trim(); }
    var matchPrice = cardPrice.match(/\$\s*[\d\.]+/);
    if (matchPrice) { cardPrice = matchPrice[0]; }
    var cardDesc = $card.find('.elementor-element-7b8c9d6').text().trim();

    $title.text(cardTitle || 'Plato Destacado');
    $price.text(cardPrice || '$0.00');
    $desc.text(cardDesc || 'Delicioso plato tradicional panameño preparado al momento.');
    $addBtn.attr('data-id', pid);

    var videoUrl = dishVideoMap[pid] || dishVideoMap['default'];
    $iframe.attr('src', formatEmbedUrl(videoUrl));

    $modal.addClass('is-open');
    $('body').css('overflow', 'hidden');
  });

  // Cerrar modal
  function closeModal() {
    $modal.removeClass('is-open');
    $iframe.attr('src', '');
    $('body').css('overflow', '');
  }

  $('#eg-modal-close-btn, .eg-modal-overlay').on('click', function() {
    closeModal();
  });

  $(document).on('keydown', function(e) {
    if (e.key === 'Escape' && $modal.hasClass('is-open')) {
      closeModal();
    }
  });

  // Agregar al pedido desde el modal
  $addBtn.on('click', function(e) {
    var pid = $(this).attr('data-id');
    closeModal();
    if (typeof woosq_open === 'function' && pid) {
      woosq_open(pid);
    } else {
      $('.post-' + pid + ' .woosq-btn').trigger('click');
    }
  });
